package view;

import model.entities.Plant;
import model.entities.Zombie;
import view.resources.BackgroundRenderer;
import view.resources.ResourceLoader;

import javax.swing.*;
import java.awt.*;
import java.util.List;

public class GameRenderer {
    private ResourceLoader resourceLoader;
    private BackgroundRenderer backgroundRenderer;
    private UIRenderer uiRenderer;
    private GridRenderer gridRenderer;
    private EntityRenderer entityRenderer;

    // 可配置开关：是否绘制网格、是否绘制UI（默认都开启）
    private boolean showGrid = true;
    private boolean showUI = true;

    public GameRenderer(ResourceLoader resourceLoader) {
        this.resourceLoader = resourceLoader;
        this.backgroundRenderer = new BackgroundRenderer(resourceLoader);
        this.uiRenderer = new UIRenderer();
        this.gridRenderer = new GridRenderer();
        this.entityRenderer = new EntityRenderer(resourceLoader);
    }

    public void render(Graphics g, JPanel panel, List<Plant> plants, List<Zombie> zombies, int sunCount) {
        // 新顺序：背景 → 兜底背景 → 实体 → 网格 → UI
        backgroundRenderer.render(g, panel);
        renderBackgroundFallback(g, panel); // 新增兜底，确保背景一定可见
        entityRenderer.render(g, panel, plants, zombies);
        if (showGrid) {
            gridRenderer.render(g);
        }
        if (showUI) {
            uiRenderer.render(g, sunCount, plants.size(), zombies.size());
        }
    }

    // 新增：背景兜底绘制（裁剪源图左上 0,0 到面板大小）
    private void renderBackgroundFallback(Graphics g, JPanel panel) {
        Image bg = resourceLoader.getAwImage("main_lawn");
        if (bg == null) {
            try {
                // 强制一次同步加载绝对路径，避免键名解析失败
                resourceLoader.loadImage("main_lawn", "/backgrounds/main_lawn.jpg");
            } catch (Exception ignore) {}
            bg = resourceLoader.getAwImage("main_lawn");
        }
        if (bg != null) {
            int w = panel.getWidth();
            int h = panel.getHeight();
            int srcW = Math.max(0, Math.min(bg.getWidth(panel), w));
            int srcH = Math.max(0, Math.min(bg.getHeight(panel), h));
            if (srcW > 0 && srcH > 0) {
                g.drawImage(bg, 0, 0, w, h, 0, 0, srcW, srcH, panel);
            }
        }
    }

    // 调试/配置入口
    public void setShowGrid(boolean showGrid) { this.showGrid = showGrid; }
    public void setShowUI(boolean showUI) { this.showUI = showUI; }
    public boolean isShowGrid() { return showGrid; }
    public boolean isShowUI() { return showUI; }
}

