                    x, LAWN_START_Y + GRID_ROWS * GRID_CELL_HEIGHT);
        }
    }

    /** 单元标签（列,行，0-based） */
    private void drawGridLabels(Graphics g) {
        g.setColor(Color.BLACK);
        g.setFont(new Font("Arial", Font.PLAIN, 10));
        for (int row = 0; row < GRID_ROWS; row++) {
            for (int col = 0; col < GRID_COLS; col++) {
                int x = LAWN_START_X + col * GRID_CELL_WIDTH + 5;
                int y = LAWN_START_Y + row * GRID_CELL_HEIGHT + 15;
                g.drawString(col + "," + row, x, y);
            }
        }
    }
}

package view.resources;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;

/**
 * 资源加载器（线程安全单例）
 *
 * 职责：
 * - 维护键名到类路径的资源映射（resourcePathMap）；
 * - 统一加载图片/动图（ImageInterface 抽象），并缓存（imageCache）；
 * - 提供“键名加载”与“显式路径加载”，前者会先解析实际可见路径；
 * - 提供工具：resourceExists（可见性探测）、resolvePathForKey（解析结果）、统计报告。
 *
 * 约定：
 * - 资源应打包到类路径（例如 /backgrounds/main_lawn.jpg, /plants/*.gif, /zombies/*.gif）；
 * - 键名建议：main_lawn, plant_*, zombie_*；
 * - 线程安全：加载过程中以 loadingInProgress 防重入，缓存使用 ConcurrentHashMap。
 */
public class ResourceLoader {
    private static ResourceLoader instance;
    private final Map<String, ImageInterface> imageCache;
    private final Set<String> loadingInProgress;
    private final Map<String ,String> resourcePathMap; // 键名->首选资源路径的映射

    // 后台加载线程池（单线程守护，避免阻塞 EDT）
    private final ExecutorService executor;

    private ResourceLoader() {
        this.imageCache = new ConcurrentHashMap<>();
        this.loadingInProgress = Collections.synchronizedSet(new HashSet<>());
        this.resourcePathMap = new HashMap<>();
        this.executor = Executors.newSingleThreadExecutor(new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "ResourceLoader-Background");
                t.setDaemon(true);
                return t;
            }
        });
        // 统一为绝对类路径
        resourcePathMap.put("main_lawn", "/backgrounds/main_lawn.jpg");
        // 植物/僵尸 GIF（使用绝对路径，解析会做存在性确认）
        resourcePathMap.put("plant_sunflower", "/plants/sunflower.gif");
        resourcePathMap.put("plant_peashooter", "/plants/peashooter.gif");
        resourcePathMap.put("zombie_basic", "/zombies/normalZombie.gif");
    }

    public static synchronized ResourceLoader getInstance() {
        if (instance == null) {
            instance = new ResourceLoader();
        }
        return instance;
    }

    /**
     * 显式路径加载（绕过解析，要求 path 已是解析后的可见类路径）
     * - 带有加载过程日志；
     * - 加载成功后放入缓存，后续同键名直接复用。
     */
    public ImageInterface loadImage(String key, String path) {
        if (imageCache.containsKey(key)) {
            return imageCache.get(key);
        }
        // 修复：Set 使用 contains 而非 containsKey
        if (loadingInProgress.contains(key)) {
            return imageCache.get(key);
        }
        try {
            loadingInProgress.add(key);
            // 新增：规范化显式传入路径并挑选可见候选（自动补前导“/”）
            String resolvedPath = normalizeExplicitPath(key, path);
            System.out.println("[ResourceLoader] 加载资源: " + key + " -> " + resolvedPath);
            ImageInterface image = UnifiedImageFactory.createImage(key, resolvedPath);
            boolean ok = false;
            try {
                ok = image.load();
            } catch (Throwable t) {
                System.err.println("[ResourceLoader] 解码/加载失败: " + key + " -> " + t.getMessage());
            }
            if (ok) {
                imageCache.put(key, image);
                return image;
            } else {
                System.err.println("[ResourceLoader] 加载失败: " + key + " [" + resolvedPath + "]");
                return null;
            }
        } finally {
            loadingInProgress.remove(key);
        }
    }

    /**
     * 键名加载（增强版，支持按 key 自动推断）
     * - 优先使用 resourcePathMap 配置项解析；
     * - 若无配置，尝试按 key 模式推断常见目录与扩展名（优先 GIF -> PNG -> JPG）；
     * - 若推断失败，则尝试回退到基础资源（zombie_basic / plant_peashooter）；
     * - 不再直接抛出异常，无法解析时返回 null 并打印警告，调用方可选择忽略或重试。
     */
    public ImageInterface loadImage(String key){
        if(imageCache.containsKey(key)){
            return imageCache.get(key);
        }

        String configured = resourcePathMap.get(key);
        String resolved = null;

        if (configured != null) {
            resolved = resolveResourcePath(key, configured);
            if (resolved == null) {
                System.err.println("[ResourceLoader] 配置路径解析失败: " + key + " -> " + configured);
            }
        } else {
            // 无显式配置，尝试基于 key 的启发式推断
            String suffix = key;
            if (key.contains("_")) suffix = key.substring(key.indexOf('_') + 1);
            String[] dirs;
            if (key.startsWith("zombie_")) dirs = new String[] {"zombies", ""};
            else if (key.startsWith("plant_")) dirs = new String[] {"plants", ""};
            else dirs = new String[] {"images", "assets", ""};

            String[] exts = new String[] {"gif", "png", "jpg", "jpeg"};
            for (String d : dirs) {
                for (String ext : exts) {
                    if (suffix == null || suffix.isEmpty()) continue;
                    String cand = (d == null || d.isEmpty()) ? ("/" + suffix + "." + ext) : ("/" + d + "/" + suffix + "." + ext);
                    if (existsOnClassPath(cand)) {
                        resolved = cand;
                        break;
                    }
                    // 也尝试不带前导斜杠的变体
                    String rel = cand.startsWith("/") ? cand.substring(1) : cand;
                    if (existsOnClassPath("/" + rel) || existsOnClassPath(rel)) {
                        resolved = "/" + rel;
                        break;
                    }
                }
                if (resolved != null) break;
            }

            // 回退到基础资源（若仍未解析）
            if (resolved == null) {
                if (key.startsWith("zombie_")) {
                    String base = resourcePathMap.getOrDefault("zombie_basic", "/zombies/normalZombie.gif");
                    resolved = resolveResourcePath("zombie_basic", base);
                } else if (key.startsWith("plant_")) {
                    String base = resourcePathMap.getOrDefault("plant_peashooter", "/plants/peashooter.gif");
                    resolved = resolveResourcePath("plant_peashooter", base);
                }
            }

            if (resolved == null) {
                System.err.println("[ResourceLoader] 无法为键名推断路径: " + key);
            } else {
                System.out.println("[ResourceLoader] 推断路径: " + key + " -> " + resolved);
            }
        }

        if (resolved == null) {
            // 无法解析出路径：记录并安全返回 null（调用方可根据 null 做回退）
            System.err.println("[ResourceLoader] 未在类路径找到资源键: " + key);
            return null;
        }

        return loadImage(key, resolved);
    }

    /** 批量加载（失败项打印错误并跳过） */
    public Map<String, ImageInterface> loadImages(Map<String, String> imageMap) {
        Map<String, ImageInterface> result = new HashMap<>();
        for (Map.Entry<String, String> entry : imageMap.entrySet()) {
            try {
                ImageInterface image = loadImage(entry.getKey(), entry.getValue());
                result.put(entry.getKey(), image);
            } catch (Exception e) {
                System.err.println("批量加载失败: " + entry.getKey() + " - " + e.getMessage());
            }
        }
        return result;
    }

    /** 获取或惰性加载（键名） */
    public ImageInterface getImage(String key) {
        ImageInterface image = imageCache.get(key);
        if (image == null) {
            //如果缓存没有，尝试加载（路径会先被解析）
            return loadImage(key);
        }
        return image;
    }

    /** 安全获取（仅缓存中存在才返回） */
    public ImageInterface getImageSafe(String key) {
        return imageCache.get(key);
    }

    /** 直接返回 AWT Image（若已加载且存在）。若未加载则异步触发加载并立即返回 null（避免阻塞 EDT） */
    public Image getAwImage(String key){
        ImageInterface imageInterface = imageCache.get(key);
        if (imageInterface != null && imageInterface.isLoaded()) {
            return imageInterface.getImage();
        }
        // 若尚未加载，尝试异步加载（若已有加载进程则不重复提交）
        if (!loadingInProgress.contains(key)) {
            // 使用后台线程避免在 EDT 上进行 I/O/解码
            executor.submit(() -> {
                try {
                    // 尝试按键名加载（内部会解析路径）
                    loadImage(key);
                } catch (Exception e) {
                    System.err.println("[ResourceLoader] 异步加载失败: " + key + " - " + e.getMessage());
                }
            });
        }
        return null;
    }

    /** 缓存状态查询/释放/重载等生命周期方法 */
    public boolean isImageLoaded(String key) {
        ImageInterface image = imageCache.get(key);
        return image != null && image.isLoaded();
    }

    public void unloadImage(String key) {
        ImageInterface image = imageCache.remove(key);
        if (image != null) {
            image.unload();
        }
    }

    public void unloadAll() {
        for (ImageInterface image : imageCache.values()) {
            try {
                image.unload();
            } catch (Exception ignore) {}
        }
        imageCache.clear();
        loadingInProgress.clear();
        try {
            executor.shutdownNow();
        } catch (Exception ignore) {}
    }

    public void reloadImage(String key) {
        ImageInterface oldImage = imageCache.get(key);
        if (oldImage != null) {
            String path = oldImage.getPath();
            unloadImage(key);
            loadImage(key, path);
        }
    }

    // ==================== 工具方法 ====================

    /**
     * 路径解析：
     * - 将键名的首选路径 primary 规范化为多个候选（相对/绝对），
     * - 针对 main_lawn/plant_/zombie_添加常见子目录（/backgrounds/plants/zombies），
     * - 返回第一个在类路径上可见的形式（统一以“/绝对”形式返回）。
     **/
    private String resolveResourcePath(String key, String primary) {
        List<String> candidates = new ArrayList<>();

        // 规范化起始候选
        String p = primary;
        String fileName = extractFileName(p);
        String base = fileNameWithoutExt(fileName);
        String ext = fileExt(fileName);
        if (ext == null || ext.isEmpty()) ext = "jpg";

        candidates.add(p);
        candidates.add(trimLeadingSlash(p));
        if ("main_lawn".equals(key)) {
            String main = "/backgrounds/" + base + ".jpg";
            candidates.add(main);
            // 移除重复前导斜杠的候选，避免生成 "//backgrounds/..." 变体
        }
        if ("plant_sunflower".equals(key) || "plant_peashooter".equals(key) || "zombie_basic".equals(key)) {
            if (!ext.equalsIgnoreCase("gif")) ext = "gif";
            String[] dirs = key.startsWith("zombie") ? new String[]{"zombies"} : new String[]{"plants"};
            for (String d : dirs) {
                String path = d + "/" + base + "." + ext;
                candidates.add(path);
                candidates.add("/" + path);
            }
        }

        for (String c : candidates) {
            String abs = c.startsWith("/") ? c : "/" + c;
            String rel = c.startsWith("/") ? c.substring(1) : c;
            if (existsOnClassPath(abs)) return abs;
            if (existsOnClassPath(rel)) return "/" + rel;
        }
        return null;
    }

    /** 类路径可见性探测（绝对/相对形式都会尝试） */
    private boolean existsOnClassPath(String path) {
        URL u1 = ResourceLoader.class.getResource(path.startsWith("/")? path : "/" + path);
        if (u1 != null) return true;
        ClassLoader cl = Thread.currentThread().getContextClassLoader();
        URL u2 = (cl == null) ? null : cl.getResource(path.startsWith("/")? path.substring(1) : path);
        return u2 != null;
    }

    // 路径字符串工具（文件名/扩展名/去前导斜杠）
    private String extractFileName(String path) {
        if (path == null) return "";
        int idx = path.lastIndexOf('/');
        return idx >= 0 ? path.substring(idx + 1) : path;
    }

    private String fileNameWithoutExt(String name) {
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(0, dot) : name;
    }

    private String fileExt(String name) {
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(dot + 1) : "";
    }

    private String trimLeadingSlash(String p) {
        if (p == null) return null;
        return p.startsWith("/") ? p.substring(1) : p;
    }

    /** 暴露：解析键名对应路径（可能返回 null） */
    public String resolvePathForKey(String key) {
        String configured = resourcePathMap.get(key);
        if (configured == null) return null;
        return resolveResourcePath(key, configured);
    }

    /** 暴露：仅检测可见性（不触发真实加载） */
    public boolean resourceExists(String path) {
        if (path == null || path.isEmpty()) return false;
        String abs = path.startsWith("/") ? path : "/" + path;
        String rel = path.startsWith("/") ? path.substring(1) : path;
        return existsOnClassPath(abs) || existsOnClassPath(rel);
    }

    /** 显式路径规范化：优先返回类路径上存在的“/绝对”形式，否则回退为加前导斜杠 */
    private String normalizeExplicitPath(String key, String path) {
        if (path == null || path.trim().isEmpty()) return path;
        String p = path.trim();
        List<String> candidates = new ArrayList<>();
        // 原样、绝对、相对三种常见变体
        candidates.add(p);
        if (p.startsWith("/")) {
            candidates.add(p.substring(1));
        } else {
            candidates.add("/" + p);
        }
        // 针对常用键提供合理回退候选
        if ("main_lawn".equals(key)) {
            candidates.add("/backgrounds/main_lawn.jpg");
        } else if (key != null) {
            if (key.startsWith("plant_")) {
                String name = key.substring("plant_".length());
                candidates.add("/plants/" + name + ".gif");
                candidates.add("/plants/" + name + ".png");
            } else if (key.startsWith("zombie_")) {
                String name = key.substring("zombie_".length());
                candidates.add("/zombies/" + name + ".gif");
                candidates.add("/zombies/" + name + ".png");
            }
        }
        for (String c : candidates) {
            String abs = c.startsWith("/") ? c : "/" + c;
            String rel = c.startsWith("/") ? c.substring(1) : c;
            if (existsOnClassPath(abs) || existsOnClassPath(rel)) {
                return abs;
            }
        }
        // 若均不可见，仍返回“/绝对”形式，避免后续实现因相对路径直接失败
        return p.startsWith("/") ? p : ("/" + p);
    }

    // ============ 统计与报告（调试/诊断用） ============
    /**
     * 获取资源统计信息
     */
    public ResourceStats getResourceStats() {
        int total = imageCache.size();
        long loaded = imageCache.values().stream().filter(ImageInterface::isLoaded).count();
        long animated = imageCache.values().stream().filter(ImageInterface::isAnimated).count();
        long memoryEstimate = estimateMemoryUsage();

        return new ResourceStats(total, loaded, animated, memoryEstimate);
    }

    /**
     * 估算内存使用
     */
    private long estimateMemoryUsage() {
        return imageCache.values().stream()
                .filter(ImageInterface::isLoaded)
                .mapToLong(image -> (long) image.getWidth() * image.getHeight() * 4) // 4 bytes per pixel
                .sum();
    }

    /**
     * 打印资源状态报告
     */
    public void printResourceReport() {
        ResourceStats stats = getResourceStats();
        System.out.println("=== 资源加载器状态报告 ===");
        System.out.printf("总资源数: %d\n", stats.getTotalCount());
        System.out.printf("已加载: %d\n", stats.getLoadedCount());
        System.out.printf("动画资源: %d\n", stats.getAnimatedCount());
        System.out.printf("预估内存: %d KB\n", stats.getMemoryUsage() / 1024);
        System.out.println("-----------------------");

        imageCache.forEach((key, image) -> {
            String status = image.isLoaded() ? "✓" : "✗";
            String type = image.isAnimated() ? "动画" : "静态";
            System.out.printf("%s %s: %s %dx%d\n",
                    status, key, type, image.getWidth(), image.getHeight());
        });
        System.out.println("=======================");
    }

    /** 统计信息快照 */
    public static class ResourceStats {
        private final int totalCount;
        private final long loadedCount;
        private final long animatedCount;
        private final long memoryUsage;

        public ResourceStats(int totalCount, long loadedCount, long animatedCount, long memoryUsage) {
            this.totalCount = totalCount;
            this.loadedCount = loadedCount;
            this.animatedCount = animatedCount;
            this.memoryUsage = memoryUsage;
        }

        // Getters
        public int getTotalCount() { return totalCount; }
        public long getLoadedCount() { return loadedCount; }
        public long getAnimatedCount() { return animatedCount; }
        public long getMemoryUsage() { return memoryUsage; }
    }

    // ============ 简单测试入口（可独立运行） ============
    /**
     * 简单测试主方法
     * 直接运行此类即可测试资源加载功能
     */
    public static void main(String[] args) {
        System.out.println("=== 资源加载器简单测试 ===");

        ResourceLoader loader = ResourceLoader.getInstance();

        // 测试1: 基本加载（使用已验证可见路径）
        System.out.println("1. 测试基本加载:");
        try {
            ImageInterface image = loader.loadImage("test_bg", "/backgrounds/main_lawn.jpg");
            if (image.isLoaded()) {
                System.out.println("   ✓ 加载成功: " + image.getWidth() + "x" + image.getHeight());
            }
        } catch (Exception e) {
            System.out.println("   ✗ 加载失败: " + e.getMessage());
        }

        // 测试2: 动画加载（使用 plants 目录的 gif）
        System.out.println("2. 测试动画加载:");
        try {
            ImageInterface anim = loader.loadImage("test_plant", "/plants/sunflower.gif");
            if (anim.isLoaded()) {
                System.out.println("   ✓ 动画加载: " + anim.isAnimated() + ", " + anim.getWidth() + "x" + anim.getHeight());
            }
        } catch (Exception e) {
            System.out.println("   ✗ 动画加载失败: " + e.getMessage());
        }

        // 测试3: 资源统计
        System.out.println("3. 资源统计:");
        ResourceStats stats = loader.getResourceStats();
        System.out.println("   总资源: " + stats.getTotalCount() + ", 已加载: " + stats.getLoadedCount());

        // 测试4: 打印报告
        System.out.println("4. 资源报告:");
        loader.printResourceReport();

        // 自检示例
        System.out.println("=== 自检示例 ===");
        String testKey = "main_lawn";
        String resolvedPath = loader.resolvePathForKey(testKey);
        System.out.println("解析键名 '" + testKey + "' 对应的路径: " + resolvedPath);
        System.out.println("资源是否存在: " + loader.resourceExists(resolvedPath));

        System.out.println("=== 测试完成 ===");
    }
}

package view.resources;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;

/**
 * 资源加载器（线程安全单例）
 *
 * 职责：
 * - 维护键名到类路径的资源映射（resourcePathMap）；
 * - 统一加载图片/动图（ImageInterface 抽象），并缓存（imageCache）；
 * - 提供“键名加载”与“显式路径加载”，前者会先解析实际可见路径；
 * - 提供工具：resourceExists（可见性探测）、resolvePathForKey（解析结果）、统计报告。
 *
 * 约定：
 * - 资源应打包到类路径（例如 /backgrounds/main_lawn.jpg, /plants/*.gif, /zombies/*.gif）；
 * - 键名建议：main_lawn, plant_*, zombie_*；
 * - 线程安全：加载过程中以 loadingInProgress 防重入，缓存使用 ConcurrentHashMap。
 */
public class ResourceLoader {
    private static ResourceLoader instance;
    private final Map<String, ImageInterface> imageCache;
    private final Set<String> loadingInProgress;
    private final Map<String ,String> resourcePathMap; // 键名->首选资源路径的映射

    // 后台加载线程池（单线程守护，避免阻塞 EDT）
    private final ExecutorService executor;

    private ResourceLoader() {
        this.imageCache = new ConcurrentHashMap<>();
        this.loadingInProgress = Collections.synchronizedSet(new HashSet<>());
        this.resourcePathMap = new HashMap<>();
        this.executor = Executors.newSingleThreadExecutor(new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "ResourceLoader-Background");
                t.setDaemon(true);
                return t;
            }
        });
        // 统一为绝对类路径
        resourcePathMap.put("main_lawn", "/backgrounds/main_lawn.jpg");
        // 植物/僵尸 GIF（使用绝对路径，解析会做存在性确认）
        resourcePathMap.put("plant_sunflower", "/plants/sunflower.gif");
        resourcePathMap.put("plant_peashooter", "/plants/peashooter.gif");
        resourcePathMap.put("zombie_basic", "/zombies/normalZombie.gif");
    }

    public static synchronized ResourceLoader getInstance() {
        if (instance == null) {
            instance = new ResourceLoader();
        }
        return instance;
    }

    /**
     * 显式路径加载（绕过解析，要求 path 已是解析后的可见类路径）
     * - 带有加载过程日志；
     * - 加载成功后放入缓存，后续同键名直接复用。
     */
    public ImageInterface loadImage(String key, String path) {
        if (imageCache.containsKey(key)) {
            return imageCache.get(key);
        }
        // 修复：Set 使用 contains 而非 containsKey
        if (loadingInProgress.contains(key)) {
            return imageCache.get(key);
        }
        try {
            loadingInProgress.add(key);
            // 新增：规范化显式传入路径并挑选可见候选（自动补前导“/”）
            String resolvedPath = normalizeExplicitPath(key, path);
            System.out.println("[ResourceLoader] 加载资源: " + key + " -> " + resolvedPath);
            ImageInterface image = UnifiedImageFactory.createImage(key, resolvedPath);
            boolean ok = false;
            try {
                ok = image.load();
            } catch (Throwable t) {
                System.err.println("[ResourceLoader] 解码/加载失败: " + key + " -> " + t.getMessage());
            }
            if (ok) {
                imageCache.put(key, image);
                return image;
            } else {
                System.err.println("[ResourceLoader] 加载失败: " + key + " [" + resolvedPath + "]");
                return null;
            }
        } finally {
            loadingInProgress.remove(key);
        }
    }

    /**
     * 键名加载（增强版，支持按 key 自动推断）
     * - 优先使用 resourcePathMap 配置项解析；
     * - 若无配置，尝试按 key 模式推断常见目录与扩展名（优先 GIF -> PNG -> JPG）；
     * - 若推断失败，则尝试回退到基础资源（zombie_basic / plant_peashooter）；
     * - 不再直接抛出异常，无法解析时返回 null 并打印警告，调用方可选择忽略或重试。
     */
    public ImageInterface loadImage(String key){
        if(imageCache.containsKey(key)){
            return imageCache.get(key);
        }

        String configured = resourcePathMap.get(key);
        String resolved = null;

        if (configured != null) {
            resolved = resolveResourcePath(key, configured);
            if (resolved == null) {
                System.err.println("[ResourceLoader] 配置路径解析失败: " + key + " -> " + configured);
            }
        } else {
            // 无显式配置，尝试基于 key 的启发式推断
            String suffix = key;
            if (key.contains("_")) suffix = key.substring(key.indexOf('_') + 1);
            String[] dirs;
            if (key.startsWith("zombie_")) dirs = new String[] {"zombies", ""};
            else if (key.startsWith("plant_")) dirs = new String[] {"plants", ""};
            else dirs = new String[] {"images", "assets", ""};

            String[] exts = new String[] {"gif", "png", "jpg", "jpeg"};
            for (String d : dirs) {
                for (String ext : exts) {
                    if (suffix == null || suffix.isEmpty()) continue;
                    String cand = (d == null || d.isEmpty()) ? ("/" + suffix + "." + ext) : ("/" + d + "/" + suffix + "." + ext);
                    if (existsOnClassPath(cand)) {
                        resolved = cand;
                        break;
                    }
                    // 也尝试不带前导斜杠的变体
                    String rel = cand.startsWith("/") ? cand.substring(1) : cand;
                    if (existsOnClassPath("/" + rel) || existsOnClassPath(rel)) {
                        resolved = "/" + rel;
                        break;
                    }
                }
                if (resolved != null) break;
            }

            // 回退到基础资源（若仍未解析）
            if (resolved == null) {
                if (key.startsWith("zombie_")) {
                    String base = resourcePathMap.getOrDefault("zombie_basic", "/zombies/normalZombie.gif");
                    resolved = resolveResourcePath("zombie_basic", base);
                } else if (key.startsWith("plant_")) {
                    String base = resourcePathMap.getOrDefault("plant_peashooter", "/plants/peashooter.gif");
                    resolved = resolveResourcePath("plant_peashooter", base);
                }
            }

            if (resolved == null) {
                System.err.println("[ResourceLoader] 无法为键名推断路径: " + key);
            } else {
                System.out.println("[ResourceLoader] 推断路径: " + key + " -> " + resolved);
            }
        }

        if (resolved == null) {
            // 无法解析出路径：记录并安全返回 null（调用方可根据 null 做回退）
            System.err.println("[ResourceLoader] 未在类路径找到资源键: " + key);
            return null;
        }

        return loadImage(key, resolved);
    }

    /** 批量加载（失败项打印错误并跳过） */
    public Map<String, ImageInterface> loadImages(Map<String, String> imageMap) {
        Map<String, ImageInterface> result = new HashMap<>();
        for (Map.Entry<String, String> entry : imageMap.entrySet()) {
            try {
                ImageInterface image = loadImage(entry.getKey(), entry.getValue());
                result.put(entry.getKey(), image);
            } catch (Exception e) {
                System.err.println("批量加载失败: " + entry.getKey() + " - " + e.getMessage());
            }
        }
        return result;
    }

    /** 获取或惰性加载（键名） */
    public ImageInterface getImage(String key) {
        ImageInterface image = imageCache.get(key);
        if (image == null) {
            //如果缓存没有，尝试加载（路径会先被解析）
            return loadImage(key);
        }
        return image;
    }

    /** 安全获取（仅缓存中存在才返回） */
    public ImageInterface getImageSafe(String key) {
        return imageCache.get(key);
    }

    /** 直接返回 AWT Image（若已加载且存在）。若未加载则异步触发加载并立即返回 null（避免阻塞 EDT） */
    public Image getAwImage(String key){
        ImageInterface imageInterface = imageCache.get(key);
        if (imageInterface != null && imageInterface.isLoaded()) {
            return imageInterface.getImage();
        }
        // 若尚未加载，尝试异步加载（若已有加载进程则不重复提交）
        if (!loadingInProgress.contains(key)) {
            // 使用后台线程避免在 EDT 上进行 I/O/解码
            executor.submit(() -> {
                try {
                    // 尝试按键名加载（内部会解析路径）
                    loadImage(key);
                } catch (Exception e) {
                    System.err.println("[ResourceLoader] 异步加载失败: " + key + " - " + e.getMessage());
                }
            });
        }
        return null;
    }

    /** 缓存状态查询/释放/重载等生命周期方法 */
    public boolean isImageLoaded(String key) {
        ImageInterface image = imageCache.get(key);
        return image != null && image.isLoaded();
    }

    public void unloadImage(String key) {
        ImageInterface image = imageCache.remove(key);
        if (image != null) {
            image.unload();
        }
    }

    public void unloadAll() {
        for (ImageInterface image : imageCache.values()) {
            try {
                image.unload();
            } catch (Exception ignore) {}
        }
        imageCache.clear();
        loadingInProgress.clear();
        try {
            executor.shutdownNow();
        } catch (Exception ignore) {}
    }

    public void reloadImage(String key) {
        ImageInterface oldImage = imageCache.get(key);
        if (oldImage != null) {
            String path = oldImage.getPath();
            unloadImage(key);
            loadImage(key, path);
        }
    }

    // ==================== 工具方法 ====================

    /**
     * 路径解析：
     * - 将键名的首选路径 primary 规范化为多个候选（相对/绝对），
     * - 针对 main_lawn/plant_/zombie_添加常见子目录（/backgrounds/plants/zombies），
     * - 返回第一个在类路径上可见的形式（统一以“/绝对”形式返回）。
     **/
    private String resolveResourcePath(String key, String primary) {
        List<String> candidates = new ArrayList<>();

        // 规范化起始候选
        String p = primary;
        String fileName = extractFileName(p);
        String base = fileNameWithoutExt(fileName);
        String ext = fileExt(fileName);
        if (ext == null || ext.isEmpty()) ext = "jpg";

        candidates.add(p);
        candidates.add(trimLeadingSlash(p));
        if ("main_lawn".equals(key)) {
            String main = "/backgrounds/" + base + ".jpg";
            candidates.add(main);
            // 移除重复前导斜杠的候选，避免生成 "//backgrounds/..." 变体
        }
        if ("plant_sunflower".equals(key) || "plant_peashooter".equals(key) || "zombie_basic".equals(key)) {
            if (!ext.equalsIgnoreCase("gif")) ext = "gif";
            String[] dirs = key.startsWith("zombie") ? new String[]{"zombies"} : new String[]{"plants"};
            for (String d : dirs) {
                String path = d + "/" + base + "." + ext;
                candidates.add(path);
                candidates.add("/" + path);
            }
        }

        for (String c : candidates) {
            String abs = c.startsWith("/") ? c : "/" + c;
            String rel = c.startsWith("/") ? c.substring(1) : c;
            if (existsOnClassPath(abs)) return abs;
            if (existsOnClassPath(rel)) return "/" + rel;
        }
        return null;
    }

    /** 类路径可见性探测（绝对/相对形式都会尝试） */
    private boolean existsOnClassPath(String path) {
        URL u1 = ResourceLoader.class.getResource(path.startsWith("/")? path : "/" + path);
        if (u1 != null) return true;
        ClassLoader cl = Thread.currentThread().getContextClassLoader();
        URL u2 = (cl == null) ? null : cl.getResource(path.startsWith("/")? path.substring(1) : path);
        return u2 != null;
    }

    // 路径字符串工具（文件名/扩展名/去前导斜杠）
    private String extractFileName(String path) {
        if (path == null) return "";
        int idx = path.lastIndexOf('/');
        return idx >= 0 ? path.substring(idx + 1) : path;
    }

    private String fileNameWithoutExt(String name) {
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(0, dot) : name;
    }

    private String fileExt(String name) {
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(dot + 1) : "";
    }

    private String trimLeadingSlash(String p) {
        if (p == null) return null;
        return p.startsWith("/") ? p.substring(1) : p;
    }

    /** 暴露：解析键名对应路径（可能返回 null） */
    public String resolvePathForKey(String key) {
        String configured = resourcePathMap.get(key);
        if (configured == null) return null;
        return resolveResourcePath(key, configured);
    }

    /** 暴露：仅检测可见性（不触发真实加载） */
    public boolean resourceExists(String path) {
        if (path == null || path.isEmpty()) return false;
        String abs = path.startsWith("/") ? path : "/" + path;
        String rel = path.startsWith("/") ? path.substring(1) : path;
        return existsOnClassPath(abs) || existsOnClassPath(rel);
    }

    /** 显式路径规范化：优先返回类路径上存在的“/绝对”形式，否则回退为加前导斜杠 */
    private String normalizeExplicitPath(String key, String path) {
        if (path == null || path.trim().isEmpty()) return path;
        String p = path.trim();
        List<String> candidates = new ArrayList<>();
        // 原样、绝对、相对三种常见变体
        candidates.add(p);
        if (p.startsWith("/")) {
            candidates.add(p.substring(1));
        } else {
            candidates.add("/" + p);
        }
        // 针对常用键提供合理回退候选
        if ("main_lawn".equals(key)) {
            candidates.add("/backgrounds/main_lawn.jpg");
        } else if (key != null) {
            if (key.startsWith("plant_")) {
                String name = key.substring("plant_".length());
                candidates.add("/plants/" + name + ".gif");
                candidates.add("/plants/" + name + ".png");
            } else if (key.startsWith("zombie_")) {
                String name = key.substring("zombie_".length());
                candidates.add("/zombies/" + name + ".gif");
                candidates.add("/zombies/" + name + ".png");
            }
        }
        for (String c : candidates) {
            String abs = c.startsWith("/") ? c : "/" + c;
            String rel = c.startsWith("/") ? c.substring(1) : c;
            if (existsOnClassPath(abs) || existsOnClassPath(rel)) {
                return abs;
            }
        }
        // 若均不可见，仍返回“/绝对”形式，避免后续实现因相对路径直接失败
        return p.startsWith("/") ? p : ("/" + p);
    }

    // ============ 统计与报告（调试/诊断用） ============
    /**
     * 获取资源统计信息
     */
    public ResourceStats getResourceStats() {
        int total = imageCache.size();
        long loaded = imageCache.values().stream().filter(ImageInterface::isLoaded).count();
        long animated = imageCache.values().stream().filter(ImageInterface::isAnimated).count();
        long memoryEstimate = estimateMemoryUsage();

        return new ResourceStats(total, loaded, animated, memoryEstimate);
    }

    /**
     * 估算内存使用
     */
    private long estimateMemoryUsage() {
        return imageCache.values().stream()
                .filter(ImageInterface::isLoaded)
                .mapToLong(image -> (long) image.getWidth() * image.getHeight() * 4) // 4 bytes per pixel
                .sum();
    }

    /**
     * 打印资源状态报告
     */
    public void printResourceReport() {
        ResourceStats stats = getResourceStats();
        System.out.println("=== 资源加载器状态报告 ===");
        System.out.printf("总资源数: %d\n", stats.getTotalCount());
        System.out.printf("已加载: %d\n", stats.getLoadedCount());
        System.out.printf("动画资源: %d\n", stats.getAnimatedCount());
        System.out.printf("预估内存: %d KB\n", stats.getMemoryUsage() / 1024);
        System.out.println("-----------------------");

        imageCache.forEach((key, image) -> {
            String status = image.isLoaded() ? "✓" : "✗";
            String type = image.isAnimated() ? "动画" : "静态";
            System.out.printf("%s %s: %s %dx%d\n",
                    status, key, type, image.getWidth(), image.getHeight());
        });
        System.out.println("=======================");
    }

    /** 统计信息快照 */
    public static class ResourceStats {
        private final int totalCount;
        private final long loadedCount;
        private final long animatedCount;
        private final long memoryUsage;

        public ResourceStats(int totalCount, long loadedCount, long animatedCount, long memoryUsage) {
            this.totalCount = totalCount;
            this.loadedCount = loadedCount;
            this.animatedCount = animatedCount;
            this.memoryUsage = memoryUsage;
        }

        // Getters
        public int getTotalCount() { return totalCount; }
        public long getLoadedCount() { return loadedCount; }
        public long getAnimatedCount() { return animatedCount; }
        public long getMemoryUsage() { return memoryUsage; }
    }

    // ============ 简单测试入口（可独立运行） ============
    /**
     * 简单测试主方法
     * 直接运行此类即可测试资源加载功能
     */
    public static void main(String[] args) {
        System.out.println("=== 资源加载器简单测试 ===");

        ResourceLoader loader = ResourceLoader.getInstance();

        // 测试1: 基本加载（使用已验证可见路径）
        System.out.println("1. 测试基本加载:");
        try {
            ImageInterface image = loader.loadImage("test_bg", "/backgrounds/main_lawn.jpg");
            if (image.isLoaded()) {
                System.out.println("   ✓ 加载成功: " + image.getWidth() + "x" + image.getHeight());
            }
        } catch (Exception e) {
            System.out.println("   ✗ 加载失败: " + e.getMessage());
        }

        // 测试2: 动画加载（使用 plants 目录的 gif）
        System.out.println("2. 测试动画加载:");
        try {
            ImageInterface anim = loader.loadImage("test_plant", "/plants/sunflower.gif");
            if (anim.isLoaded()) {
                System.out.println("   ✓ 动画加载: " + anim.isAnimated() + ", " + anim.getWidth() + "x" + anim.getHeight());
            }
        } catch (Exception e) {
            System.out.println("   ✗ 动画加载失败: " + e.getMessage());
        }

        // 测试3: 资源统计
        System.out.println("3. 资源统计:");
        ResourceStats stats = loader.getResourceStats();
        System.out.println("   总资源: " + stats.getTotalCount() + ", 已加载: " + stats.getLoadedCount());

        // 测试4: 打印报告
        System.out.println("4. 资源报告:");
        loader.printResourceReport();

        // 自检示例
        System.out.println("=== 自检示例 ===");
        String testKey = "main_lawn";
        String resolvedPath = loader.resolvePathForKey(testKey);
        System.out.println("解析键名 '" + testKey + "' 对应的路径: " + resolvedPath);
        System.out.println("资源是否存在: " + loader.resourceExists(resolvedPath));

        System.out.println("=== 测试完成 ===");
    }
}

package view.resources;

import javax.swing.*;

/**
 * 统一图片资源工厂
 * 根据文件类型自动创建合适的图片对象
 */
public class UnifiedImageFactory {

    /**
     * 根据文件路径自动判断类型并创建图片对象
     */
    public static ImageInterface createImage(String key, String path) {
        if (path == null || path.trim().isEmpty()) {
            throw new IllegalArgumentException("图片路径不能为空");
        }
        // 新增：规范类路径资源，确保使用“/绝对”形式（忽略 URL/本地绝对路径）
        String normalized = normalizeClasspathPath(path);

        String lowerPath = normalized.toLowerCase().trim();

        if (lowerPath.endsWith(".gif")) {
            return new AnimatedImage(key, normalized);
        } else if (lowerPath.endsWith(".png") ||
                lowerPath.endsWith(".jpg") ||
                lowerPath.endsWith(".jpeg") ||
                lowerPath.endsWith(".bmp")) {
            return new StaticImage(key, normalized);
        } else {
            throw new IllegalArgumentException("不支持的图片格式: " + normalized);
        }
    }

    /**
     * 明确指定类型创建图片对象
     */
    public static ImageInterface createImage(String key, String path, boolean forceAnimated) {
        if (forceAnimated) {
            return new AnimatedImage(key, path);
        } else {
            return new StaticImage(key, path);
        }
    }

    /**
     * 创建测试图片
     */
//    public static ImageInterface createTestImage(String key, int width, int height, boolean animated) {
//        ImageIcon testIcon = TestImageGenerator.generateTestImage(key, width, height, animated);
//        if (animated) {
//            AnimatedImage image = new AnimatedImage(key, "/test/" + key + ".gif");
//            image.imageIcon = testIcon;
//            image.loaded = true;
//            image.actuallyAnimated = animated;
//            return image;
//        } else {
//            StaticImage image = new StaticImage(key, "/test/" + key + ".png");
//            image.imageIcon = testIcon;
//            image.loaded = true;
//            return image;
//        }
//    }

    /** 仅对类路径资源做规范化：补全前导“/”；URL/本地绝对路径原样返回 */
    private static String normalizeClasspathPath(String path) {
        String p = path.trim();
        // URL 或 file: / Windows 盘符 / UNC 路径直接返回
        if (p.matches("^[a-zA-Z]+:.*") || p.matches("^[a-zA-Z]:[\\\\/].*") || p.startsWith("\\\\")) {
            return p;
        }
        return p.startsWith("/") ? p : ("/" + p);
    }
}

